"""Generate SELL3 and independent prices, or verify with --check."""
from pathlib import Path
import argparse
import csv
import hashlib
import io
import json

directory = Path(__file__).resolve().parent
project = directory.parents[1]
parser = argparse.ArgumentParser()
parser.add_argument('--check', action='store_true')
args = parser.parse_args()
manifest = json.loads((directory / 'manifest.json').read_text())
def read_pinned(name, key):
    raw = (directory / name).read_bytes()
    assert hashlib.sha256(raw).hexdigest() == manifest[key]
    return raw, list(csv.DictReader(raw.decode().splitlines()))
source_bytes, source = read_pinned('source-rows.csv','source_rows_sha256')
catalog_bytes, rows = read_pinned('catalog.csv','catalog_sha256')
price_source_bytes, price_source = read_pinned('price-source-rows.csv','price_source_rows_sha256')
price_bytes, prices = read_pinned('sale-prices.csv','sale_prices_sha256')
assert len(rows) == len(source) == manifest['catalog_count'] == 1
assert [int(r['id']) for r in rows] == manifest['selection']['ids'] == [3]
assert sum(int(r['weight']) for r in rows) == manifest['total_selected_weight'] == 20
assert manifest['stable_local_slots'] == {'3':0}
assert len(manifest['previous_catalog_sha256']) == 30
old = {}
for original, expected in manifest['previous_catalog_sha256'].items():
    raw = (directory.parent / original / 'catalog.csv').read_bytes()
    old_manifest = json.loads((directory.parent / original / 'manifest.json').read_text())
    assert hashlib.sha256(raw).hexdigest() == expected == old_manifest['catalog_sha256']
    for row in csv.DictReader(raw.decode().splitlines()):
        id = int(row['id'])
        assert id != 3 and id not in old, 'catalog ID collision'
        old[id] = row
assert len(old) == 215
row = source[0]
assert (row['id'], row['type'], row['attack_kind'], row['price'], row['weight']) == ('3','TRADE','SELL','5','20')
for field in ('attack_extra','defense_kind','defense_extra','attribute','value','sub_value','hit_rate'):
    assert row[field] == ''
normalized = io.StringIO(newline='')
writer = csv.writer(normalized, lineterminator='\n')
writer.writerow(['id','label','kind','attack','boost','defense','hp','mp','price','weight','discardable'])
writer.writerow([3,'legacy-003','trade',0,0,0,0,0,5,20,1])
assert normalized.getvalue().encode() == catalog_bytes
assert len(prices) == len(price_source) == manifest['sale_price_count'] == 216
ids = sorted([*old,3])
assert [int(r['id']) for r in prices] == [int(r['id']) for r in price_source] == ids
assert 4 not in ids
assert max(int(r['price']) for r in prices) == manifest['max_sale_price'] == 30
assert [int(r['id']) for r in prices if int(r['price']) == 30] == manifest['max_sale_price_ids'] == [56,186]
for price, original in zip(prices,price_source):
    id = int(price['id'])
    assert int(price['price']) == int(original['price'] or 0)
    assert int(original['weight']) > 0
    if id in old and 'price' in old[id]: assert int(price['price']) == int(old[id]['price'])
assert {int(r['id']):int(r['price']) for r in prices if r['id'] in ['216','220','221','245']} == {216:15,220:25,221:15,245:0}
header = (project / 'include/godfield/selling.hpp').read_text()
assert manifest['catalog_sha256'] in header and manifest['sale_prices_sha256'] in header
assert 'max_sale_price = 30' in header and 'sale_price_count = 216' in header
